const body = $json.body || $json;
const text = body.text || body.message || body.media?.transcription || '';
const lower = text.toLowerCase();
const attrs = {
  neighborhood: lower.includes('alto do ipiranga') ? 'Alto do Ipiranga' : null,
  street: lower.includes('rui barbosa') ? 'Rua Rui Barbosa' : lower.includes('bento vieira') ? 'Rua Bento Vieira' : null,
  property_type: lower.includes('sobrado') ? 'sobrado' : lower.includes('casa') ? 'casa' : null,
  bedrooms: /3|tres|três/.test(lower) && /dorm/.test(lower) ? 3 : null,
  parking_spaces: /2|duas|dois/.test(lower) && /(vaga|garagem|carro)/.test(lower) ? 2 : null,
  visual: lower.includes('portao azul') || lower.includes('portão azul') ? 'portao azul' : null,
  wants_broker: lower.includes('corretor'),
  wants_visit: /(visita|sábado|sabado|domingo|horário|horario|agendar)/.test(lower),
  nonexistent: lower.includes('castelo') || lower.includes('helicoptero')
};
const intent = attrs.wants_broker ? 'handoff' : attrs.wants_visit ? 'schedule_visit' : 'property_search';
return [{ json: { provider: body.provider || 'mock', phone: body.phone || '5511999990000', name: body.name || 'Cliente Teste', text, intent, attrs, raw: body } }];

const properties = [
  { title: 'Sobrado na Rua Bento Vieira com portao azul', property_type: 'sobrado', neighborhood: 'Alto do Ipiranga', street: 'Rua Bento Vieira', bedrooms: 3, parking_spaces: 2, visual: 'portao azul', short_description: 'Sobrado de 3 dormitorios com 2 vagas e portao azul no Alto do Ipiranga.', total_score: 9.2 },
  { title: 'Sobrado na Ricardo Jafet', property_type: 'sobrado', neighborhood: 'Alto do Ipiranga', street: 'Avenida Ricardo Jafet', bedrooms: 3, parking_spaces: 1, visual: 'fachada neutra', short_description: 'Sobrado de 3 dormitorios proximo a Ricardo Jafet.', total_score: 7.1 },
  { title: 'Sobrado na Arcipreste Andrade', property_type: 'sobrado', neighborhood: 'Alto do Ipiranga', street: 'Rua Arcipreste Andrade', bedrooms: 3, parking_spaces: 2, visual: 'jardim', short_description: 'Sobrado de 3 dormitorios e 2 vagas em rua tranquila.', total_score: 7.5 },
  { title: 'Casa na Rua Rui Barbosa perto da padaria', property_type: 'casa', neighborhood: 'Centro', street: 'Rua Rui Barbosa', bedrooms: 3, parking_spaces: 1, visual: 'casa terrea', short_description: 'Casa de 3 dormitorios na Rua Rui Barbosa, perto da padaria.', total_score: 8.8 }
];
const a = $json.attrs;
if (a.nonexistent) return [{ json: { ...$json, candidates: [] } }];
const candidates = properties.map((p) => {
  let score = 0;
  if (a.neighborhood && p.neighborhood === a.neighborhood) score += 2;
  if (a.street && p.street === a.street) score += 3;
  if (a.property_type && p.property_type === a.property_type) score += 2;
  if (a.bedrooms && p.bedrooms === a.bedrooms) score += 1;
  if (a.parking_spaces && p.parking_spaces >= a.parking_spaces) score += 1;
  if (a.visual && p.visual.includes(a.visual)) score += 4;
  return { ...p, total_score: score + p.total_score / 10 };
}).filter((p) => p.total_score > 0.8).sort((a, b) => b.total_score - a.total_score).slice(0, 3);
return [{ json: { ...$json, candidates } }];

const candidates = $json.candidates || [];
let reply;
if ($json.intent === 'handoff') {
  reply = 'Claro, vou pedir para um corretor chamar voce em poucos minutos. Enquanto isso, ja posso tentar deixar uma visita pre-agendada: prefere sabado pela manha ou domingo as 14h?';
} else if ($json.intent === 'schedule_visit') {
  reply = 'Perfeito, vou consultar a agenda do corretor e deixar sabado pela manha como primeira opcao. Posso confirmar esse horario para voce?';
} else if (!candidates.length) {
  reply = 'Nao encontrei esse imovel com seguranca. Voce lembra alguma pista objetiva: rua, bairro, dormitorios, garagem, cor do portao, faixa de preco ou referencia do site?';
} else if ($json.attrs.street === 'Rua Rui Barbosa') {
  reply = 'Na Rua Rui Barbosa temos uma casa de 3 dormitorios perto da padaria. E essa que o senhor viu?';
} else if ($json.attrs.visual === 'portao azul') {
  const p = candidates[0];
  reply = `Pelo que voce descreveu, parece ser ${p.title}. ${p.short_description} Quer que eu te passe os detalhes principais ou ja veja uma visita?`;
} else {
  const opts = candidates.map((p) => p.street.replace('Rua ', '').replace('Avenida ', '')).join(', ');
  reply = `No Alto do Ipiranga temos opcoes com 3 dormitorios na ${opts}. O senhor lembra se era alguma dessas ruas?`;
}
return [{ json: { ok: true, mode: 'mock', phone: $json.phone, reply, candidates } }];
